tool.command:
set -euo pipefail;

RUN_DIR="\$(pwd)";
BUILD_DIR="\${RUN_DIR}/input_build";
INPUT_ROOT="\${BUILD_DIR}/00_input";
INTERNAL_ARCHIVE="\${RUN_DIR}/module4_input.tar.gz";

echo "[INFO] Preparing Module 4 input structure";

rm -rf "\${BUILD_DIR}";
rm -f "\${INTERNAL_ARCHIVE}";

mkdir -p "\${INPUT_ROOT}/01_eggNOG_functional_annotation/01_bacterial_protein_genes";
mkdir -p "\${INPUT_ROOT}/01_eggNOG_functional_annotation/02_plasmid_protein_genes";
mkdir -p "\${INPUT_ROOT}/03_genbank/01_Prodigal/01_bacterial";
mkdir -p "\${INPUT_ROOT}/03_genbank/01_Prodigal/02_plasmid";
mkdir -p "\${INPUT_ROOT}/03_genbank/01_metadata";
mkdir -p "\${INPUT_ROOT}/03_genbank/03_eggNOG/01_bacteria";
mkdir -p "\${INPUT_ROOT}/03_genbank/03_eggNOG/02_plasmid";
mkdir -p "\${INPUT_ROOT}/04_hypothetical_genes/01_Re-annotated_bacterial_genbank";
mkdir -p "\${INPUT_ROOT}/04_hypothetical_genes/02_Reference_bacterial_genbank";
mkdir -p "\${INPUT_ROOT}/04_hypothetical_genes/03_Re-annotated_plasmids_genbank";
mkdir -p "\${INPUT_ROOT}/04_hypothetical_genes/04_Reference_plasmids_genbank";
mkdir -p "\${INPUT_ROOT}/06_nr_NCBI";

echo "[INFO] Staging bacterial eggNOG FAA files";

#for $f in $functional_annotation_inputs.bacterial_faa
cp -L '$f' "\${INPUT_ROOT}/01_eggNOG_functional_annotation/01_bacterial_protein_genes/${f.element_identifier}.faa";
#end for

#if $functional_annotation_inputs.plasmid_faa
echo "[INFO] Staging plasmid eggNOG FAA files";

#for $f in $functional_annotation_inputs.plasmid_faa
cp -L '$f' "\${INPUT_ROOT}/01_eggNOG_functional_annotation/02_plasmid_protein_genes/${f.element_identifier}.faa";
#end for
#end if

echo "[INFO] Staging bacterial Prodigal FNA files";

#for $f in $bacterial_prodigal_inputs.bacterial_fna
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/01_bacterial/${f.element_identifier}.fna";
#end for

echo "[INFO] Staging bacterial Prodigal GFF files";

#for $f in $bacterial_prodigal_inputs.bacterial_gff
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/01_bacterial/${f.element_identifier}.gff";
#end for

echo "[INFO] Staging bacterial Prodigal FAA files";

#for $f in $bacterial_prodigal_inputs.bacterial_prodigal_faa
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/01_bacterial/${f.element_identifier}.faa";
#end for

#if $plasmid_prodigal_inputs.plasmid_fna
echo "[INFO] Staging plasmid Prodigal FNA files";

#for $f in $plasmid_prodigal_inputs.plasmid_fna
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/02_plasmid/${f.element_identifier}.fna";
#end for
#end if

#if $plasmid_prodigal_inputs.plasmid_gff
echo "[INFO] Staging plasmid Prodigal GFF files";

#for $f in $plasmid_prodigal_inputs.plasmid_gff
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/02_plasmid/${f.element_identifier}.gff";
#end for
#end if

#if $plasmid_prodigal_inputs.plasmid_prodigal_faa
echo "[INFO] Staging plasmid Prodigal FAA files";

#for $f in $plasmid_prodigal_inputs.plasmid_prodigal_faa
cp -L '$f' "\${INPUT_ROOT}/03_genbank/01_Prodigal/02_plasmid/${f.element_identifier}.faa";
#end for
#end if

echo "[INFO] Staging metadata";

cp -L '$metadata_settings.metadata' "\${INPUT_ROOT}/03_genbank/01_metadata/03_replicon_metadata.tsv";

echo "[INFO] Staging reference bacterial GenBank files";

#for $f in $reference_genbank_inputs.reference_bacterial_genbank
cp -L '$f' "\${INPUT_ROOT}/04_hypothetical_genes/02_Reference_bacterial_genbank/${f.element_identifier}.gb";
#end for

#if $reference_genbank_inputs.reference_plasmid_genbank
echo "[INFO] Staging reference plasmid GenBank files";

#for $f in $reference_genbank_inputs.reference_plasmid_genbank
cp -L '$f' "\${INPUT_ROOT}/04_hypothetical_genes/04_Reference_plasmids_genbank/${f.element_identifier}.gb";
#end for
#end if

echo "[INFO] Staging static Module 4 resources";

for resource in go-basic.obo kegg_pathway_titles.tsv pfam_duf_map.tsv; do
    test -s "$__tool_directory__/\${resource}" || {
        echo "[FATAL] Missing tool resource: \${resource}";
        exit 1;
    };
    cp -L "$__tool_directory__/\${resource}" "\${INPUT_ROOT}/\${resource}";
done;

echo "[INFO] Staged input files";

find "\${INPUT_ROOT}" -type f -printf '%P\t%s bytes\n' | sort;

test -s "\${INPUT_ROOT}/03_genbank/01_metadata/03_replicon_metadata.tsv" || {
    echo "[FATAL] Metadata file is missing or empty";
    exit 1;
};

test -n "\$(find "\${INPUT_ROOT}/01_eggNOG_functional_annotation/01_bacterial_protein_genes" -maxdepth 1 -type f -print -quit)" || {
    echo "[FATAL] Bacterial eggNOG FAA directory is empty";
    exit 1;
};

test -n "\$(find "\${INPUT_ROOT}/03_genbank/01_Prodigal/01_bacterial" -maxdepth 1 -type f -print -quit)" || {
    echo "[FATAL] Bacterial Prodigal directory is empty";
    exit 1;
};

test -n "\$(find "\${INPUT_ROOT}/04_hypothetical_genes/02_Reference_bacterial_genbank" -maxdepth 1 -type f -print -quit)" || {
    echo "[FATAL] Reference bacterial GenBank directory is empty";
    exit 1;
};

echo "[INFO] Creating internal Module 4 archive";

tar -czf "\${INTERNAL_ARCHIVE}" -C "\${BUILD_DIR}" 00_input;

test -s "\${INTERNAL_ARCHIVE}" || {
    echo "[FATAL] Internal input archive was not created";
    exit 1;
};

echo "[INFO] Internal archive contents";

tar -tzf "\${INTERNAL_ARCHIVE}";

echo "[INFO] Running Module 4";

bash '$__tool_directory__/run_module4.sh' "\${INTERNAL_ARCHIVE}" '$metadata_settings.threads' '$__tool_directory__';

echo "[INFO] Validating final output archives";

for output_file in module4_results.tar.gz module4_logs.tar.gz module4_work.tar.gz module4_completed_input.tar.gz; do
    test -s "\${RUN_DIR}/\${output_file}" || {
        echo "[FATAL] Missing or empty output: \${output_file}";
        exit 1;
    };
    tar -tzf "\${RUN_DIR}/\${output_file}" >/dev/null || {
        echo "[FATAL] Invalid TAR.GZ output: \${output_file}";
        exit 1;
    };
done;

ls -lh "\${RUN_DIR}/module4_results.tar.gz" "\${RUN_DIR}/module4_logs.tar.gz" "\${RUN_DIR}/module4_work.tar.gz" "\${RUN_DIR}/module4_completed_input.tar.gz";

echo "[INFO] RECAP-PROK Module 4 completed successfully";

tool.help:
RECAP-PROK Module 4

This wrapper accepts Galaxy datasets and dataset collections instead of
requiring the user to upload a prepared TAR or ZIP archive.

The wrapper reconstructs the Module 4 input directory internally, creates
a temporary TAR.GZ archive, and passes that archive to the previously
validated run_module4.sh script.

The following file-name patterns must be preserved where applicable:

- Re-annotated_*.faa
- PLRe-annotated_*.faa

The tool fails instead of returning empty green outputs when:

- no inputs are staged;
- a required input group is empty;
- the metadata file is empty;
- the internal archive is missing;
- run_module4.sh fails;
- any expected final archive is missing, empty, or invalid.
